export const catalog = Object.freeze(Object.fromEntries(Object.entries(pairs).map(([key, [en, ru]]) => [key, Object.freeze({en, ru})])));
export function localeFromSearch(search = '') {
  try { return new URLSearchParams(String(search).replace(/^\?/, '')).get('lang') === 'ru' ? 'ru' : 'en'; }
  catch { return 'en'; }
}
const locale = lang => lang === 'ru' ? 'ru' : 'en';
const escapeText = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]));
export function t(key, lang = 'en', params = {}) {
  const entry = catalog[key];
  if (!entry) throw new Error(`Unknown message key: ${key}`);
  return entry[locale(lang)].replace(/\{([a-zA-Z][\w]*)\}/g, (_, name) => escapeText(params?.[name]));
}

