const ruToEn = new Map(), enToRu = new Map();
for (const [a, b] of backend) {
  if (/[А-Яа-яЁё]/.test(a)) {ruToEn.set(a, b); enToRu.set(b, a);}
  else {enToRu.set(a, b); ruToEn.set(b, a);}
}
// Patterns match whole messages; escaping interpolation prevents HTML injection even if a caller
// mistakenly renders a returned diagnostic as HTML instead of textContent.
const patterns = [
  [/^Большая серия: пиксели усреднены в плоскости (\d+)×\1 \(с (\d+×\d+×\d+) до (\d+×\d+×\d+)\); все исходные позиции срезов по Z сохранены\. Сегментация и объём приблизительные: тонкие очаги и границы могли измениться\. Исходные DICOM не изменены\.$/, (m, l) => `Large series: pixels were averaged in-plane ${m[1]}×${m[1]} (from ${m[2]} to ${m[3]}); all original Z slice positions were preserved. Segmentation and volume are approximate: thin lesions and boundaries may have changed. Original DICOM files were not modified.`],
  [/^Большой объём: разрешение в плоскости уменьшено в (\d+) раза \(до ([\d×]+)\); исходные срезы по оси Z сохранены\.$/, m => `Large volume: in-plane resolution reduced by ${m[1]} (to ${m[2]}); original Z slices were preserved.`],
  [/^Интерполировано срезов: (\d+)\. Интерполяция не восстанавливает отсутствующие детали; проверь результат перед количественным анализом\.$/, m => `Interpolated slices: ${m[1]}. Interpolation cannot restore missing details; review before quantitative analysis.`],
  [/^Не найдена подходящая DICOM-серия: проверено (\d+) файлов, пропущено (\d+)\. (.+)$/s, (m, l) => `No suitable DICOM series found: checked ${m[1]} files, skipped ${m[2]}. ${translateBackend(m[3], l)}`],
  [/^Transfer Syntax (\S+) пока не поддерживается\. Экспортируй DICOM без сжатия\.$/, m => `Transfer Syntax ${m[1]} is not supported yet. Export uncompressed DICOM.`],
  [/^Preview only: (\d+) voxels would be added and (\d+) removed\. Review before acceptance\.$/, m => `Предпросмотр: будет добавлено ${m[1]} вокселей и удалено ${m[2]}. Проверьте перед принятием.`],
  [/^Preview only: (\d+) voxels would be removed; thin regions may disappear\. Review before acceptance\.$/, m => `Предпросмотр: будет удалено ${m[1]} вокселей; тонкие области могут исчезнуть. Проверьте перед принятием.`],
  [/^Mask ROI exceeds the (\d+)-voxel budget; no partial preview\.$/, m => `Область маски превышает лимит ${m[1]} вокселей; частичный предпросмотр отсутствует.`],
  [/^Closing halo exceeds the (\d+)-voxel budget; no partial preview\.$/, m => `Область закрытия превышает лимит ${m[1]} вокселей; частичный предпросмотр отсутствует.`],
  [/^Computational failure: (.+)$/s, (m, l) => `${l === 'ru' ? 'Ошибка вычисления: ' : 'Computational failure: '}${translateBackend(m[1], l)}`],
];
export function translateBackend(text, lang = 'en') {
  if (typeof text !== 'string' || !text) return text;
  const target = locale(lang);
  const known = target === 'en' ? ruToEn.get(text) : enToRu.get(text);
  if (known !== undefined) return known;
  // Patterns are deliberately anchored: never replace substrings in user filenames or unknown errors.
  for (const [regex, render] of patterns) {
    const m = regex.exec(text);
    if (m) {
      const sourceIsRussian = /[А-Яа-яЁё]/.test(regex.source);
      if ((target === 'en') === sourceIsRussian) return render(m, target);
      return text;
    }
  }
  return text;
}
